// Header site search: lazy loading, the build-time index, live-page indexing,
// keyboard navigation, the /zh tree, and missing or stale index data. The
// main paths run against the index generated by this build.

const MANIFEST = '/search-index/manifest.json';

function openSearch() {
  cy.get('[data-testid="site-search-toggle"]').click();
  cy.get('[data-testid="site-search-input"]').should('be.focused');
}

describe('Site search', () => {
  beforeEach(() => {
    cy.intercept('GET', MANIFEST).as('manifest');
    cy.intercept('GET', '/search-index/*/*.json').as('indexFile');
    // Browser-side page fetching is gone: any fetch of page HTML from the
    // dialog would carry exactly this Accept header (the old crawler's).
    cy.intercept({ method: 'GET', headers: { accept: 'text/html' } }).as('pageFetch');
  });

  it('does not load the search chunk or the index until opened', () => {
    cy.visit('/about');
    cy.get('[data-testid="site-search-toggle"]').should(
      'have.attr',
      'aria-label',
      'Search InferenceX',
    );
    cy.get('[data-testid="site-search-dialog"]').should('not.exist');
    cy.get('@manifest.all').should('have.length', 0);
  });

  it('loads the versioned index on open and searches it locally', () => {
    cy.visit('/about');
    openSearch();
    cy.wait('@manifest');
    cy.wait('@indexFile')
      .its('request.url')
      .should('match', /\/search-index\/[0-9a-f]{16}\/en\.json$/u);
    cy.get('[data-testid="site-search-status"]')
      .should('have.attr', 'data-state', 'ready')
      .invoke('text')
      .should('match', /^\d+ pages indexed · \d+ summary only · built \w{3} \d{1,2}, \d{4}$/u);

    cy.get('[data-testid="site-search-input"]').type('mi355x vs b200');
    cy.get('[data-testid="site-search-result"]')
      .should('have.length.greaterThan', 1)
      .filter('[href^="/chips/mi355x-vs-b200"]')
      .should('exist');
    // A summary-only page is labelled as such.
    cy.get('[data-testid="site-search-input"]').clear().type('agentx methodology');
    cy.get('[data-testid="site-search-result"][href="/agentx/methodology"]').should(
      'contain.text',
      'Summary',
    );
    cy.get('@pageFetch.all').should('have.length', 0);
    cy.get('@indexFile.all').should('have.length', 1);
  });

  it('opens with Ctrl+K, moves through results with the arrow keys and opens the selection', () => {
    cy.visit('/about');
    cy.get('body').type('{ctrl}k');
    cy.get('[data-testid="site-search-status"]').should('have.attr', 'data-state', 'ready');
    cy.get('[data-testid="site-search-input"]').type('TTFT definition');
    const option = '[data-testid="site-search-dialog"] [role="option"]';
    cy.get(option).first().should('have.attr', 'aria-selected', 'true');
    cy.get('[data-testid="site-search-input"]').type('{downarrow}');
    cy.get(option).eq(1).should('have.attr', 'aria-selected', 'true');
    // Up from the first result wraps to the last; down wraps back to the first.
    cy.get('[data-testid="site-search-input"]').type('{uparrow}{uparrow}');
    cy.get(option).last().should('have.attr', 'aria-selected', 'true');
    cy.get('[data-testid="site-search-input"]').type('{downarrow}');
    cy.get(option).first().should('have.attr', 'aria-selected', 'true');
    cy.get('[data-testid="site-search-result"]')
      .first()
      .invoke('attr', 'href')
      .then((href) => {
        cy.get('[data-testid="site-search-input"]').type('{enter}');
        cy.location('pathname').should('eq', String(href).split('#')[0]);
      });
    cy.get('[data-testid="site-search-dialog"]').should('not.exist');
  });

  it('uses the Chinese index and UI on /zh pages', () => {
    cy.visit('/zh/about');
    cy.get('[data-testid="site-search-toggle"]')
      .should('have.attr', 'aria-label', '搜索 InferenceX')
      .click();
    cy.wait('@indexFile')
      .its('request.url')
      .should('match', /\/zh\.json$/u);
    cy.get('[data-testid="site-search-status"]')
      .should('have.attr', 'data-state', 'ready')
      .and('contain.text', '已索引');
    cy.get('[data-testid="site-search-input"]').type('首个 token 延迟');
    cy.get('[data-testid="site-search-result"]')
      .first()
      .should('have.attr', 'href')
      .and('match', /^\/zh\//u);
  });

  it('keeps the current page searchable when the index cannot load', () => {
    cy.intercept('GET', MANIFEST, { statusCode: 503, body: 'unavailable' }).as('manifestDown');
    cy.visit('/about');
    openSearch();
    cy.wait('@manifestDown');
    cy.get('[data-testid="site-search-status"]')
      .should('have.attr', 'data-state', 'unavailable')
      .and('have.text', 'Site index unavailable · searching this page only');
    // The About page FAQ is on screen, so it is still found from the live DOM.
    cy.get('[data-testid="site-search-input"]').type('open source');
    cy.get('[data-testid="site-search-result"]')
      .first()
      .should('have.attr', 'href')
      .and('match', /^\/about/u);
    cy.get('[data-testid="site-search-input"]').clear().type('zzqx');
    cy.get('[data-testid="site-search-empty"]').should(
      'have.text',
      'No matches on this page. The site index could not be loaded.',
    );
  });

  it('recovers when a cached manifest names a version replaced by a new deploy', () => {
    cy.request(MANIFEST).then(({ body }) => {
      const stale = 'deadbeefdeadbeef';
      cy.intercept(
        { method: 'GET', url: MANIFEST, times: 1 },
        {
          body: {
            ...body,
            version: stale,
            locales: {
              en: { ...body.locales.en, path: `/search-index/${stale}/en.json` },
              zh: { ...body.locales.zh, path: `/search-index/${stale}/zh.json` },
            },
          },
        },
      ).as('staleManifest');
      cy.visit('/about');
      openSearch();
      cy.wait('@staleManifest');
      // The stale file is gone (404), so the engine bypasses caches for the
      // manifest and loads the version it names now.
      cy.wait('@indexFile').then(({ request, response }) => {
        expect(new URL(request.url).pathname).to.eq(`/search-index/${stale}/en.json`);
        expect(response?.statusCode).to.eq(404);
      });
      cy.wait('@manifest')
        .its('request.headers')
        .should('have.property', 'cache-control', 'no-cache');
      // The current file may come straight from the HTTP cache (it is
      // immutable), so assert on the loaded result rather than the request.
      cy.get('[data-testid="site-search-status"]').should('have.attr', 'data-state', 'ready');
      cy.get('[data-testid="site-search-input"]').type('mi355x vs b200');
      cy.get('[data-testid="site-search-result"][href^="/chips/mi355x-vs-b200"]').should('exist');
    });
  });
});
